const pageAnalysis = await browserjs(tabId, () => {
  const text = document.body.innerText;
  const links = Array.from(document.querySelectorAll('a')).map(a => ({
    text: a.textContent.trim(),
    href: a.href
  }));

  const videoLinks = links.filter(l => 
    l.text.toLowerCase().includes('video') || 
    l.href.toLowerCase().includes('video') ||
    l.href.toLowerCase().includes('youtube') ||
    l.href.toLowerCase().includes('techtalks') ||
    l.href.toLowerCase().includes('facebook') ||
    l.text.toLowerCase().includes('award') ||
    l.text.toLowerCase().includes('talk') ||
    l.text.toLowerCase().includes('schedule')
  );

  const bestPaperMatches = [];
  const regex = /best paper/gi;
  let match;
  while ((match = regex.exec(text)) !== null) {
    const start = Math.max(0, match.index - 100);
    const end = Math.min(text.length, match.index + 100);
    bestPaperMatches.push(text.slice(start, end));
  }

  return {
    videoLinks,
    bestPaperMatches,
    title: document.title
  };
});

