const bpaDetails = await browserjs(tabId, () => {
  const h2s = Array.from(document.querySelectorAll('h2'));
  const bpaH2 = h2s.find(h => h.textContent.includes('Best Paper Awards'));
  if (!bpaH2) return null;

  // Find all sibling or descendant video cards between this h2 and the next h2
  let curr = bpaH2.nextElementSibling;
  const items = [];
  while (curr && curr.tagName !== 'H2') {
    const links = Array.from(curr.querySelectorAll('a'));
    for (const a of links) {
      if (a.href.includes('/videos/')) {
        items.push({
          href: a.href,
          text: a.innerText.trim()
        });
      }
    }
    curr = curr.nextElementSibling;
  }
  return items;
});
